-- ---------- spatial indexes ----------
CREATE INDEX "fields_geom_gist" ON "fields" USING GIST ("geom");
CREATE INDEX "fields_centroid_gist" ON "fields" USING GIST ("centroid");
CREATE INDEX "admin_areas_geom_gist" ON "admin_areas" USING GIST ("geom");
CREATE INDEX "us_counties_geom_gist" ON "us_counties" USING GIST ("geom");

-- ---------- partial unique indexes (Tech Design §5.2) ----------
-- One active gather job per field (RFC §5.1).
CREATE UNIQUE INDEX "gather_jobs_one_active_per_field"
  ON "gather_jobs" ("field_id") WHERE "status" IN ('queued', 'running');

-- One active scheduled analysis run per workspace (RFC §10.2).
CREATE UNIQUE INDEX "analysis_runs_one_active_schedule_per_workspace"
  ON "analysis_runs" ("workspace_id") WHERE "status" = 'running' AND "trigger" = 'schedule';

-- One active field check per field, across runs (RFC §10.2).
CREATE UNIQUE INDEX "analysis_run_fields_one_active_per_field"
  ON "analysis_run_fields" ("field_id") WHERE "status" IN ('waiting', 'running');

-- One live recommendation per (field, type, subject, season) (RFC §10.4). Dismissed counts as live so a
-- later run updates it in place (it reopens only when the level rises) instead of creating a duplicate.
CREATE UNIQUE INDEX "recommendations_one_live"
  ON "recommendations" ("field_id", "type", "subject", "season")
  WHERE "status" IN ('open', 'accepted', 'snoozed', 'in_report', 'dismissed');

-- Unpublished outbox rows, oldest first (Tech Design §7).
CREATE INDEX "outbox_unpublished" ON "outbox" ("id") WHERE "published_at" IS NULL;
